import heapq

def match(orders):
    trades = []
    buy_heap = []   # entries: (-price, seq, id)
    sell_heap = []  # entries: (price, seq, id)
    book = {}       # id -> order info dict
    seq = 0

    for o in orders:
        typ = o[0]

        if typ == 'cancel':
            oid = o[1]
            info = book.get(oid)
            if info and info['status'] == 'active' and info['qty'] > 0:
                info['status'] = 'canceled'
            continue

        if typ == 'market':
            _, oid, side, qty = o
            price = None
        else:
            _, oid, side, price, qty = o

        remaining = qty
        info = {'side': side, 'price': price, 'qty': remaining, 'status': 'active', 'seq': seq}
        seq += 1
        book[oid] = info

        opp_heap = sell_heap if side == 'buy' else buy_heap

        while remaining > 0 and opp_heap:
            top = opp_heap[0]
            if side == 'buy':
                p, s, oid2 = top
            else:
                negp, s, oid2 = top
                p = -negp

            info2 = book.get(oid2)
            if info2 is None or info2['status'] != 'active' or info2['qty'] <= 0:
                heapq.heappop(opp_heap)
                continue

            if typ != 'market' and price is not None:
                if side == 'buy' and p > price:
                    break
                if side == 'sell' and p < price:
                    break

            # perform match
            heapq.heappop(opp_heap)
            trade_qty = min(remaining, info2['qty'])

            if side == 'buy':
                trades.append([oid, oid2, p, trade_qty])
            else:
                trades.append([oid2, oid, p, trade_qty])

            remaining -= trade_qty
            info2['qty'] -= trade_qty

            if info2['qty'] > 0:
                heapq.heappush(opp_heap, top)
            else:
                info2['status'] = 'filled'

        info['qty'] = remaining

        if typ == 'limit' and remaining > 0:
            if side == 'buy':
                heapq.heappush(buy_heap, (-price, info['seq'], oid))
            else:
                heapq.heappush(sell_heap, (price, info['seq'], oid))
            info['status'] = 'active'
        else:
            if remaining == 0:
                info['status'] = 'filled'
            else:
                info['status'] = 'canceled'

    return trades

